async function httpJson(url, options = {}) {
  const method = options.method || 'GET';

  const requestOptions = {
    method,
    url,
    headers: {
      ...(options.headers || {}),
      'Content-Type': 'application/json'
    },
    json: true
  };

  if (options.body) {
    try {
      requestOptions.body = JSON.parse(options.body);
    } catch (e) {
      requestOptions.body = options.body;
    }
  }

  try {
    return await n8nHttpRequest(requestOptions);
  } catch (error) {
    const message =
      error?.response?.body ||
      error?.message ||
      JSON.stringify(error);

    throw new Error(
      `Erro HTTP em ${url}: ${typeof message === 'string' ? message : JSON.stringify(message)}`
    );
  }
}

async function supabase(path, options = {}) {
  const baseUrl = String(CFG.SUPABASE_URL || '').replace(/\/+$/, '');
  const url = `${baseUrl}/rest/v1/${path}`;

  return await httpJson(url, {
    ...options,
    headers: {
      apikey: CFG.SUPABASE_SERVICE_ROLE_KEY,
      Authorization: `Bearer ${CFG.SUPABASE_SERVICE_ROLE_KEY}`,
      Prefer: options.prefer || 'return=representation',
      ...(options.headers || {})
    }
  });
}

async function logMessage(phone, direction, text, raw = null) {
