function classifyRiskLevel(payload) {
  const mood = Number(payload.mood_score || 0);
  const energy = Number(payload.energy_level || 0);
  const anxiety = Number(payload.anxiety_level || 0);

  if (anxiety >= 5 && mood <= 2 && energy <= 2) return 'alert';
  if (anxiety >= 5 && mood <= 2) return 'attention';

  return 'healthy';
}

