    await upsertState(
      msg.phone,
      'WAITING_MOOD',
      {
        entry_date: payload.entry_date || todayISO()
      },
      link
    );

    await sendWhatsApp(
      msg.phone,
      `Sem problema. Vamos refazer 💜

${moodQuestion()}`
    );

    return [{ json: { ok: true } }];
  }

  if (msg.textLower === '3' || msg.textLower === 'cancelar') {
    await clearState(msg.phone);

    await sendWhatsApp(
      msg.phone,
      'Registro cancelado 💜 Quando quiser, envie "diário" para começar de novo.'
    );

    return [{ json: { ok: true } }];
  }

  if (msg.textLower !== '1' && msg.textLower !== 'sim') {
